public class Solution {
    public static void bmiReport(double weightKg, double heightM) {
        double bmi = weightKg / (heightM * heightM);
        String cat = bmi < 18.5 ? "under" : (bmi < 25 ? "normal" : "over");
        System.out.println("BMI " + bmi + " " + cat);
    }
}

